-- PART 04: 시장 스냅샷·심리, 종목/지수 시세, 환율, 채권금리

CREATE TABLE "TB_MKT_SNAP" (
 "MKT_SNAP_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"BASE_DT" DATE NOT NULL,"MKT_SNAP_CD" VARCHAR(30) NOT NULL,"MKT_NM" VARCHAR(100) NOT NULL,
 "MAIN_IDX_ID" BIGINT,"MAIN_IDX_VAL" NUMERIC(20,6),"MAIN_IDX_CHG_RT" NUMERIC(10,4),"SUB_IDX_ID" BIGINT,"SUB_IDX_VAL" NUMERIC(20,6),"SUB_IDX_CHG_RT" NUMERIC(10,4),
 "FRGN_NET_AMT" NUMERIC(20,4),"INST_NET_AMT" NUMERIC(20,4),"INDV_NET_AMT" NUMERIC(20,4),"FRGN_FUT_NET_QTY" NUMERIC(20,4),
 "PGM_NET_AMT" NUMERIC(20,4),"PGM_ARB_AMT" NUMERIC(20,4),"PGM_NON_ARB_AMT" NUMERIC(20,4),"EXCH_RT" NUMERIC(20,6),"EXCH_CHG_RT" NUMERIC(10,4),
 "VOL_IDX_VAL" NUMERIC(20,6),"VOL_IDX_CHG_RT" NUMERIC(10,4),"ADV_STK_CNT" INTEGER,"DECL_STK_CNT" INTEGER,"UNCH_STK_CNT" INTEGER,"MKT_BREADTH_RT" NUMERIC(10,4),
 "NEW_HIGH_CNT" INTEGER,"NEW_LOW_CNT" INTEGER,"TURNOVER_AMT" NUMERIC(24,4),"LIQD_SCR" NUMERIC(10,4),"DATA_SRC_CD" VARCHAR(30) NOT NULL,
 "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',"DATA_AGE_MIN" INTEGER,"LAST_OK_DTTM" TIMESTAMP WITH TIME ZONE,"COLLECT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "RAW_REF" VARCHAR(500),"CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "PK_TB_MKT_SNAP" PRIMARY KEY("MKT_SNAP_ID"),CONSTRAINT "UK_TB_MKT_SNAP_01" UNIQUE("BASE_DT","MKT_SNAP_CD"),
 CONSTRAINT "FK_TB_MKT_SNAP_01" FOREIGN KEY("MAIN_IDX_ID") REFERENCES "TB_IDX"("IDX_ID"),CONSTRAINT "FK_TB_MKT_SNAP_02" FOREIGN KEY("SUB_IDX_ID") REFERENCES "TB_IDX"("IDX_ID"),
 CONSTRAINT "CK_TB_MKT_SNAP_01" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR')),CONSTRAINT "CK_TB_MKT_SNAP_02" CHECK("DATA_AGE_MIN" IS NULL OR "DATA_AGE_MIN">=0),
 CONSTRAINT "CK_TB_MKT_SNAP_03" CHECK("ADV_STK_CNT" IS NULL OR "ADV_STK_CNT">=0),CONSTRAINT "CK_TB_MKT_SNAP_04" CHECK("DECL_STK_CNT" IS NULL OR "DECL_STK_CNT">=0),CONSTRAINT "CK_TB_MKT_SNAP_05" CHECK("UNCH_STK_CNT" IS NULL OR "UNCH_STK_CNT">=0));
CREATE INDEX "IDX_TB_MKT_SNAP_01" ON "TB_MKT_SNAP"("BASE_DT" DESC); CREATE INDEX "IDX_TB_MKT_SNAP_02" ON "TB_MKT_SNAP"("MKT_SNAP_CD","BASE_DT" DESC); CREATE INDEX "IDX_TB_MKT_SNAP_03" ON "TB_MKT_SNAP"("DATA_STS");
COMMENT ON TABLE "TB_MKT_SNAP" IS '일별 시장 종합 스냅샷';
COMMENT ON COLUMN "TB_MKT_SNAP"."MKT_SNAP_ID" IS '시장 스냅샷 ID'; COMMENT ON COLUMN "TB_MKT_SNAP"."BASE_DT" IS '시장 데이터 기준일'; COMMENT ON COLUMN "TB_MKT_SNAP"."MKT_SNAP_CD" IS '시장 스냅샷 코드(KR_MARKET, US_MARKET 등)'; COMMENT ON COLUMN "TB_MKT_SNAP"."MKT_NM" IS '시장명';
COMMENT ON COLUMN "TB_MKT_SNAP"."MAIN_IDX_ID" IS '대표 기준지수 ID'; COMMENT ON COLUMN "TB_MKT_SNAP"."MAIN_IDX_VAL" IS '대표지수 값'; COMMENT ON COLUMN "TB_MKT_SNAP"."MAIN_IDX_CHG_RT" IS '대표지수 등락률'; COMMENT ON COLUMN "TB_MKT_SNAP"."SUB_IDX_ID" IS '보조 기준지수 ID'; COMMENT ON COLUMN "TB_MKT_SNAP"."SUB_IDX_VAL" IS '보조지수 값'; COMMENT ON COLUMN "TB_MKT_SNAP"."SUB_IDX_CHG_RT" IS '보조지수 등락률';
COMMENT ON COLUMN "TB_MKT_SNAP"."FRGN_NET_AMT" IS '외국인 순매수금액(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."INST_NET_AMT" IS '기관 순매수금액(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."INDV_NET_AMT" IS '개인 순매수금액(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."FRGN_FUT_NET_QTY" IS '외국인 선물 순매수수량'; COMMENT ON COLUMN "TB_MKT_SNAP"."PGM_NET_AMT" IS '프로그램 전체 순매수금액(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."PGM_ARB_AMT" IS '프로그램 차익 순매수금액(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."PGM_NON_ARB_AMT" IS '프로그램 비차익 순매수금액(원)';
COMMENT ON COLUMN "TB_MKT_SNAP"."EXCH_RT" IS '대표 환율'; COMMENT ON COLUMN "TB_MKT_SNAP"."EXCH_CHG_RT" IS '대표 환율 등락률'; COMMENT ON COLUMN "TB_MKT_SNAP"."VOL_IDX_VAL" IS '변동성지수 값'; COMMENT ON COLUMN "TB_MKT_SNAP"."VOL_IDX_CHG_RT" IS '변동성지수 등락률'; COMMENT ON COLUMN "TB_MKT_SNAP"."ADV_STK_CNT" IS '상승 종목 수'; COMMENT ON COLUMN "TB_MKT_SNAP"."DECL_STK_CNT" IS '하락 종목 수'; COMMENT ON COLUMN "TB_MKT_SNAP"."UNCH_STK_CNT" IS '보합 종목 수'; COMMENT ON COLUMN "TB_MKT_SNAP"."MKT_BREADTH_RT" IS '시장 확산도';
COMMENT ON COLUMN "TB_MKT_SNAP"."NEW_HIGH_CNT" IS '신고가 종목 수'; COMMENT ON COLUMN "TB_MKT_SNAP"."NEW_LOW_CNT" IS '신저가 종목 수'; COMMENT ON COLUMN "TB_MKT_SNAP"."TURNOVER_AMT" IS '시장 거래대금(원)'; COMMENT ON COLUMN "TB_MKT_SNAP"."LIQD_SCR" IS '시장 유동성 점수'; COMMENT ON COLUMN "TB_MKT_SNAP"."DATA_SRC_CD" IS '데이터 출처 코드'; COMMENT ON COLUMN "TB_MKT_SNAP"."DATA_STS" IS '데이터 상태(FRESH, STALE, MISSING, PARTIAL, ERROR)'; COMMENT ON COLUMN "TB_MKT_SNAP"."DATA_AGE_MIN" IS '수집시점 기준 데이터 경과시간(분)'; COMMENT ON COLUMN "TB_MKT_SNAP"."LAST_OK_DTTM" IS '마지막 정상 수집일시'; COMMENT ON COLUMN "TB_MKT_SNAP"."COLLECT_DTTM" IS '데이터 수집일시'; COMMENT ON COLUMN "TB_MKT_SNAP"."RAW_REF" IS '원천 데이터 참조정보'; COMMENT ON COLUMN "TB_MKT_SNAP"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_MKT_SNAP"."UPD_DTTM" IS '수정일시';

CREATE TABLE "TB_MKT_SENT" (
 "MKT_SENT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"BASE_DT" DATE NOT NULL,"MKT_SNAP_CD" VARCHAR(30) NOT NULL,
 "NEWS_FEAR_SCR" NUMERIC(10,4),"AI_FATIGUE_SCR" NUMERIC(10,4),"EARN_CONF_SCR" NUMERIC(10,4),"LIQD_SCR" NUMERIC(10,4),"FLOW_SCR" NUMERIC(10,4),"EXCH_PRESS_SCR" NUMERIC(10,4),"RATE_PRESS_SCR" NUMERIC(10,4),"VOL_PRESS_SCR" NUMERIC(10,4),
 "SENT_SCR" NUMERIC(10,4) NOT NULL,"SENT_PHASE" VARCHAR(20) NOT NULL,"CONF_RT" NUMERIC(10,4) NOT NULL,"STRUCT_DMG_YN" CHAR(1) NOT NULL DEFAULT 'N',"STRUCT_DMG_RT" NUMERIC(10,4),
 "REV_SIG" VARCHAR(1000),"KEY_RSN" VARCHAR(2000),"RULE_VER_NO" INTEGER NOT NULL DEFAULT 1,"DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',"CALC_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,"UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "PK_TB_MKT_SENT" PRIMARY KEY("MKT_SENT_ID"),CONSTRAINT "UK_TB_MKT_SENT_01" UNIQUE("BASE_DT","MKT_SNAP_CD"),
 CONSTRAINT "CK_TB_MKT_SENT_01" CHECK("SENT_PHASE" IN ('GREED','OPTIMISM','NEUTRAL','FATIGUE','FEAR','PANIC')),CONSTRAINT "CK_TB_MKT_SENT_02" CHECK("CONF_RT" BETWEEN 0 AND 100),CONSTRAINT "CK_TB_MKT_SENT_03" CHECK("STRUCT_DMG_YN" IN ('Y','N')),CONSTRAINT "CK_TB_MKT_SENT_04" CHECK("STRUCT_DMG_RT" IS NULL OR "STRUCT_DMG_RT" BETWEEN 0 AND 100),CONSTRAINT "CK_TB_MKT_SENT_05" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR')));
CREATE INDEX "IDX_TB_MKT_SENT_01" ON "TB_MKT_SENT"("BASE_DT" DESC); CREATE INDEX "IDX_TB_MKT_SENT_02" ON "TB_MKT_SENT"("SENT_PHASE","BASE_DT" DESC);
COMMENT ON TABLE "TB_MKT_SENT" IS '일별 시장심리 분석 결과';
COMMENT ON COLUMN "TB_MKT_SENT"."MKT_SENT_ID" IS '시장심리 ID'; COMMENT ON COLUMN "TB_MKT_SENT"."BASE_DT" IS '시장심리 기준일'; COMMENT ON COLUMN "TB_MKT_SENT"."MKT_SNAP_CD" IS '대상 시장 스냅샷 코드'; COMMENT ON COLUMN "TB_MKT_SENT"."NEWS_FEAR_SCR" IS '뉴스 공포 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."AI_FATIGUE_SCR" IS 'AI 투자 피로 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."EARN_CONF_SCR" IS '기업실적 신뢰도 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."LIQD_SCR" IS '시장 유동성 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."FLOW_SCR" IS '외국인·기관 등 수급 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."EXCH_PRESS_SCR" IS '환율 압력 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."RATE_PRESS_SCR" IS '금리 압력 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."VOL_PRESS_SCR" IS '변동성 압력 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."SENT_SCR" IS '종합 시장심리 점수'; COMMENT ON COLUMN "TB_MKT_SENT"."SENT_PHASE" IS '시장심리 단계'; COMMENT ON COLUMN "TB_MKT_SENT"."CONF_RT" IS '시장심리 판단 신뢰도(0~100)'; COMMENT ON COLUMN "TB_MKT_SENT"."STRUCT_DMG_YN" IS '시장 구조적 훼손 여부'; COMMENT ON COLUMN "TB_MKT_SENT"."STRUCT_DMG_RT" IS '시장 구조적 훼손 가능성(0~100)'; COMMENT ON COLUMN "TB_MKT_SENT"."REV_SIG" IS '시장심리 반전 확인 신호'; COMMENT ON COLUMN "TB_MKT_SENT"."KEY_RSN" IS '시장심리 핵심 판단근거'; COMMENT ON COLUMN "TB_MKT_SENT"."RULE_VER_NO" IS '시장심리 계산규칙 버전'; COMMENT ON COLUMN "TB_MKT_SENT"."DATA_STS" IS '입력 데이터 상태'; COMMENT ON COLUMN "TB_MKT_SENT"."CALC_DTTM" IS '시장심리 계산일시'; COMMENT ON COLUMN "TB_MKT_SENT"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_MKT_SENT"."UPD_DTTM" IS '수정일시';

-- 기존 종목시세 4,648건을 STK_ID 기반 구조로 전환한다.
DROP VIEW tb_prc_day;
ALTER TABLE "TB_PRC_DAY" RENAME COLUMN "ID" TO "PRC_DAY_ID"; ALTER TABLE "TB_PRC_DAY" RENAME COLUMN "TRD_DT" TO "TRADE_DT"; ALTER TABLE "TB_PRC_DAY" RENAME COLUMN "ADJ_CLS" TO "ADJ_CLS_PRC";
ALTER TABLE "TB_PRC_DAY" ADD COLUMN "STK_ID" BIGINT,ADD COLUMN "PREV_CLS_PRC" NUMERIC(20,6),ADD COLUMN "CHG_AMT" NUMERIC(20,6),ADD COLUMN "CHG_RT" NUMERIC(10,4),ALTER COLUMN "VOL" TYPE NUMERIC(24,4),ADD COLUMN "TURNOVER_AMT" NUMERIC(24,4),ADD COLUMN "HIGH_52W_PRC" NUMERIC(20,6),ADD COLUMN "LOW_52W_PRC" NUMERIC(20,6),ADD COLUMN "DD_52W_RT" NUMERIC(10,4),ADD COLUMN "ALL_HIGH_PRC" NUMERIC(20,6),ADD COLUMN "DD_HIGH_RT" NUMERIC(10,4),ADD COLUMN "DATA_SRC_CD" VARCHAR(30),ADD COLUMN "DATA_STS" VARCHAR(20) DEFAULT 'FRESH',ADD COLUMN "COLLECT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP;
UPDATE "TB_PRC_DAY" p SET "STK_ID"=s."STK_ID","DATA_SRC_CD"=CASE WHEN p."PRVDR"='YAHOO_FINANCE' THEN 'YAHOO' ELSE p."PRVDR" END,"COLLECT_DTTM"=p."MOD_DT" AT TIME ZONE 'Asia/Seoul' FROM "TB_STK" s WHERE s."MKT_CD"=p."MKT_CD" AND s."STK_CD"=p."STK_CD";
WITH x AS (SELECT "PRC_DAY_ID",lag("CLS_PRC") OVER(PARTITION BY "STK_ID" ORDER BY "TRADE_DT") prev,max("HIGH_PRC") OVER(PARTITION BY "STK_ID" ORDER BY "TRADE_DT" ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) h52,max("HIGH_PRC") OVER(PARTITION BY "STK_ID") hall,min("LOW_PRC") OVER(PARTITION BY "STK_ID" ORDER BY "TRADE_DT" ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) l52 FROM "TB_PRC_DAY") UPDATE "TB_PRC_DAY" p SET "PREV_CLS_PRC"=x.prev,"CHG_AMT"=p."CLS_PRC"-x.prev,"CHG_RT"=CASE WHEN x.prev<>0 THEN (p."CLS_PRC"-x.prev)/x.prev*100 END,"HIGH_52W_PRC"=x.h52,"LOW_52W_PRC"=x.l52,"DD_52W_RT"=CASE WHEN x.h52<>0 THEN (p."CLS_PRC"-x.h52)/x.h52*100 END,"ALL_HIGH_PRC"=x.hall,"DD_HIGH_RT"=CASE WHEN x.hall<>0 THEN (p."CLS_PRC"-x.hall)/x.hall*100 END FROM x WHERE x."PRC_DAY_ID"=p."PRC_DAY_ID";
ALTER TABLE "TB_PRC_DAY" DROP CONSTRAINT "FK_TB_PRC_DAY_STK"; ALTER TABLE "TB_PRC_DAY" DROP CONSTRAINT "UK_STK_PRC_01"; ALTER TABLE "TB_PRC_DAY" DROP CONSTRAINT "tb_overseas_stock_daily_price_pkey";
ALTER TABLE "TB_PRC_DAY" ALTER COLUMN "STK_ID" SET NOT NULL,ALTER COLUMN "DATA_SRC_CD" SET NOT NULL,ALTER COLUMN "DATA_STS" SET NOT NULL,ALTER COLUMN "COLLECT_DTTM" SET NOT NULL,ADD CONSTRAINT "PK_TB_PRC_DAY" PRIMARY KEY("PRC_DAY_ID"),ADD CONSTRAINT "UK_TB_PRC_DAY_01" UNIQUE("STK_ID","TRADE_DT"),ADD CONSTRAINT "UK_TB_PRC_DAY_LEGACY" UNIQUE("MKT_CD","STK_CD","TRADE_DT"),ADD CONSTRAINT "FK_TB_PRC_DAY_01" FOREIGN KEY("STK_ID") REFERENCES "TB_STK"("STK_ID"),ADD CONSTRAINT "CK_TB_PRC_DAY_01" CHECK("CLS_PRC">=0),ADD CONSTRAINT "CK_TB_PRC_DAY_02" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'));
CREATE INDEX "IDX_TB_PRC_DAY_01" ON "TB_PRC_DAY"("STK_ID","TRADE_DT" DESC); CREATE INDEX "IDX_TB_PRC_DAY_02" ON "TB_PRC_DAY"("TRADE_DT" DESC); CREATE INDEX "IDX_TB_PRC_DAY_03" ON "TB_PRC_DAY"("DD_HIGH_RT");
CREATE VIEW tb_prc_day AS SELECT "PRC_DAY_ID" id,"STK_CD" symbol,"TRADE_DT" trading_day,"OPEN_PRC" open_price,"HIGH_PRC" high_price,"LOW_PRC" low_price,"CLS_PRC" close_price,"ADJ_CLS_PRC" adjusted_close,"VOL" volume,"PRVDR" provider,"REG_DT" created_at,"MOD_DT" updated_at,CASE WHEN "MKT_CD"='US' THEN 'OVERSEAS' ELSE 'DOMESTIC' END market_scope FROM "TB_PRC_DAY";
COMMENT ON TABLE "TB_PRC_DAY" IS '종목별 일별 시세'; COMMENT ON COLUMN "TB_PRC_DAY"."PRC_DAY_ID" IS '일별 종목시세 ID'; COMMENT ON COLUMN "TB_PRC_DAY"."STK_ID" IS '종목 ID'; COMMENT ON COLUMN "TB_PRC_DAY"."TRADE_DT" IS '거래일'; COMMENT ON COLUMN "TB_PRC_DAY"."OPEN_PRC" IS '시가'; COMMENT ON COLUMN "TB_PRC_DAY"."HIGH_PRC" IS '고가'; COMMENT ON COLUMN "TB_PRC_DAY"."LOW_PRC" IS '저가'; COMMENT ON COLUMN "TB_PRC_DAY"."CLS_PRC" IS '종가'; COMMENT ON COLUMN "TB_PRC_DAY"."ADJ_CLS_PRC" IS '수정종가'; COMMENT ON COLUMN "TB_PRC_DAY"."PREV_CLS_PRC" IS '전일 종가'; COMMENT ON COLUMN "TB_PRC_DAY"."CHG_AMT" IS '전일 대비 가격 변동금액'; COMMENT ON COLUMN "TB_PRC_DAY"."CHG_RT" IS '전일 대비 등락률'; COMMENT ON COLUMN "TB_PRC_DAY"."VOL" IS '거래량'; COMMENT ON COLUMN "TB_PRC_DAY"."TURNOVER_AMT" IS '거래대금'; COMMENT ON COLUMN "TB_PRC_DAY"."HIGH_52W_PRC" IS '52주 최고가'; COMMENT ON COLUMN "TB_PRC_DAY"."LOW_52W_PRC" IS '52주 최저가'; COMMENT ON COLUMN "TB_PRC_DAY"."DD_52W_RT" IS '52주 최고가 대비 하락률'; COMMENT ON COLUMN "TB_PRC_DAY"."ALL_HIGH_PRC" IS '설정 기준기간 최고가'; COMMENT ON COLUMN "TB_PRC_DAY"."DD_HIGH_RT" IS '설정 기준기간 최고가 대비 하락률'; COMMENT ON COLUMN "TB_PRC_DAY"."DATA_SRC_CD" IS '데이터 출처 코드'; COMMENT ON COLUMN "TB_PRC_DAY"."DATA_STS" IS '데이터 상태'; COMMENT ON COLUMN "TB_PRC_DAY"."COLLECT_DTTM" IS '수집일시';

-- 기존 지수코드를 기준정보에 보충하고 816건을 IDX_ID 기반으로 전환한다.
INSERT INTO "TB_IDX"("IDX_CD","IDX_NM","IDX_TP","MKT_CD","CNTRY_CD","CURR_CD","DATA_SRC_CD","SRC_SYMBOL","CRT_USR_ID","UPD_USR_ID") SELECT d."IND_CD",COALESCE(d."IND_NM",d."IND_CD"),'MARKET','KRX','KR','KRW','KRX',d."IND_CD",'SYSTEM','SYSTEM' FROM (SELECT "IND_CD",max("IND_NM") "IND_NM" FROM "TB_IDX_DAY" GROUP BY "IND_CD") d WHERE NOT EXISTS(SELECT 1 FROM "TB_IDX" i WHERE i."IDX_CD"=d."IND_CD");
DROP VIEW tb_idx_day;
ALTER TABLE "TB_IDX_DAY" RENAME COLUMN "TRD_DT" TO "TRADE_DT"; ALTER TABLE "TB_IDX_DAY" RENAME COLUMN "CLCT_DT" TO "COLLECT_DTTM";
ALTER TABLE "TB_IDX_DAY" ADD COLUMN "IDX_DAY_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,ADD COLUMN "IDX_ID" BIGINT,ADD COLUMN "PREV_CLS_VAL" NUMERIC(20,6),ADD COLUMN "HIGH_52W_VAL" NUMERIC(20,6),ADD COLUMN "DD_52W_RT" NUMERIC(10,4),ADD COLUMN "ALL_HIGH_VAL" NUMERIC(20,6),ADD COLUMN "DD_HIGH_RT" NUMERIC(10,4),ADD COLUMN "DATA_SRC_CD" VARCHAR(30),ADD COLUMN "DATA_STS" VARCHAR(20) DEFAULT 'FRESH';
UPDATE "TB_IDX_DAY" d SET "IDX_ID"=i."IDX_ID","DATA_SRC_CD"=COALESCE(NULLIF(d."SRC_NM",''),'KRX'),"DATA_STS"=CASE WHEN d."CLS_VAL" IS NULL THEN 'MISSING' ELSE 'FRESH' END FROM "TB_IDX" i WHERE i."IDX_CD"=d."IND_CD";
WITH x AS (SELECT "IDX_DAY_ID",lag("CLS_VAL") OVER(PARTITION BY "IDX_ID" ORDER BY "TRADE_DT") prev,max("HIGH_VAL") OVER(PARTITION BY "IDX_ID" ORDER BY "TRADE_DT" ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) h52,max("HIGH_VAL") OVER(PARTITION BY "IDX_ID") hall FROM "TB_IDX_DAY") UPDATE "TB_IDX_DAY" d SET "PREV_CLS_VAL"=x.prev,"HIGH_52W_VAL"=x.h52,"DD_52W_RT"=CASE WHEN x.h52<>0 THEN (d."CLS_VAL"-x.h52)/x.h52*100 END,"ALL_HIGH_VAL"=x.hall,"DD_HIGH_RT"=CASE WHEN x.hall<>0 THEN (d."CLS_VAL"-x.hall)/x.hall*100 END FROM x WHERE x."IDX_DAY_ID"=d."IDX_DAY_ID";
ALTER TABLE "TB_IDX_DAY" DROP CONSTRAINT "tb_daily_market_data_pkey";
ALTER TABLE "TB_IDX_DAY" ALTER COLUMN "IDX_ID" SET NOT NULL,ALTER COLUMN "DATA_SRC_CD" SET NOT NULL,ALTER COLUMN "DATA_STS" SET NOT NULL,ALTER COLUMN "COLLECT_DTTM" TYPE TIMESTAMP WITH TIME ZONE USING "COLLECT_DTTM" AT TIME ZONE 'Asia/Seoul',ALTER COLUMN "COLLECT_DTTM" SET NOT NULL,ADD CONSTRAINT "PK_TB_IDX_DAY" PRIMARY KEY("IDX_DAY_ID"),ADD CONSTRAINT "UK_TB_IDX_DAY_01" UNIQUE("IDX_ID","TRADE_DT"),ADD CONSTRAINT "FK_TB_IDX_DAY_01" FOREIGN KEY("IDX_ID") REFERENCES "TB_IDX"("IDX_ID"),ADD CONSTRAINT "CK_TB_IDX_DAY_01" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'));
CREATE INDEX "IDX_TB_IDX_DAY_01" ON "TB_IDX_DAY"("IDX_ID","TRADE_DT" DESC); CREATE INDEX "IDX_TB_IDX_DAY_02" ON "TB_IDX_DAY"("TRADE_DT" DESC); CREATE INDEX "IDX_TB_IDX_DAY_03" ON "TB_IDX_DAY"("DD_HIGH_RT");
CREATE VIEW tb_idx_day AS SELECT "TRADE_DT" trade_date,"IND_CD" indicator_code,"IND_NM" indicator_name,"CLS_VAL" close_value,"CHG_VAL" change_value,"CHG_RT" change_rate,"SRC_NM" source_name,"COLLECT_DTTM" collected_at,"OPEN_VAL" open_value,"HIGH_VAL" high_value,"LOW_VAL" low_value,"TRD_VOL" trading_volume,"TRD_VAL" trading_value,"MKT_CAP" market_cap FROM "TB_IDX_DAY";
COMMENT ON TABLE "TB_IDX_DAY" IS '기준지수별 일별 시세'; COMMENT ON COLUMN "TB_IDX_DAY"."IDX_DAY_ID" IS '일별 기준지수 시세 ID'; COMMENT ON COLUMN "TB_IDX_DAY"."IDX_ID" IS '기준지수 ID'; COMMENT ON COLUMN "TB_IDX_DAY"."TRADE_DT" IS '거래일'; COMMENT ON COLUMN "TB_IDX_DAY"."OPEN_VAL" IS '시가 또는 시작 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."HIGH_VAL" IS '고가 또는 최고 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."LOW_VAL" IS '저가 또는 최저 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."CLS_VAL" IS '종가 또는 마감 지수값(NULL이면 MISSING)'; COMMENT ON COLUMN "TB_IDX_DAY"."PREV_CLS_VAL" IS '전일 마감 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."CHG_VAL" IS '전일 대비 지수 변동값'; COMMENT ON COLUMN "TB_IDX_DAY"."CHG_RT" IS '전일 대비 지수 등락률'; COMMENT ON COLUMN "TB_IDX_DAY"."HIGH_52W_VAL" IS '52주 최고 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."DD_52W_RT" IS '52주 최고값 대비 하락률'; COMMENT ON COLUMN "TB_IDX_DAY"."ALL_HIGH_VAL" IS '설정 기준기간 최고 지수값'; COMMENT ON COLUMN "TB_IDX_DAY"."DD_HIGH_RT" IS '설정 기준기간 최고값 대비 하락률'; COMMENT ON COLUMN "TB_IDX_DAY"."DATA_SRC_CD" IS '데이터 출처 코드'; COMMENT ON COLUMN "TB_IDX_DAY"."DATA_STS" IS '데이터 상태'; COMMENT ON COLUMN "TB_IDX_DAY"."COLLECT_DTTM" IS '수집일시';

CREATE TABLE "TB_EXCH_DAY"("EXCH_DAY_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"BASE_DT" DATE NOT NULL,"BASE_CURR_CD" VARCHAR(10) NOT NULL,"QUOTE_CURR_CD" VARCHAR(10) NOT NULL,"EXCH_RT" NUMERIC(20,6) NOT NULL,"PREV_EXCH_RT" NUMERIC(20,6),"CHG_AMT" NUMERIC(20,6),"CHG_RT" NUMERIC(10,4),"HIGH_52W_RT" NUMERIC(20,6),"LOW_52W_RT" NUMERIC(20,6),"PRESS_SCR" NUMERIC(10,4),"DATA_SRC_CD" VARCHAR(30) NOT NULL,"DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',"COLLECT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PK_TB_EXCH_DAY" PRIMARY KEY("EXCH_DAY_ID"),CONSTRAINT "UK_TB_EXCH_DAY_01" UNIQUE("BASE_DT","BASE_CURR_CD","QUOTE_CURR_CD"),CONSTRAINT "CK_TB_EXCH_DAY_01" CHECK("EXCH_RT">0),CONSTRAINT "CK_TB_EXCH_DAY_02" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR')));
CREATE INDEX "IDX_TB_EXCH_DAY_01" ON "TB_EXCH_DAY"("BASE_CURR_CD","QUOTE_CURR_CD","BASE_DT" DESC); CREATE INDEX "IDX_TB_EXCH_DAY_02" ON "TB_EXCH_DAY"("BASE_DT" DESC);
COMMENT ON TABLE "TB_EXCH_DAY" IS '통화쌍별 일별 환율'; COMMENT ON COLUMN "TB_EXCH_DAY"."EXCH_DAY_ID" IS '일별 환율 ID'; COMMENT ON COLUMN "TB_EXCH_DAY"."BASE_DT" IS '환율 기준일'; COMMENT ON COLUMN "TB_EXCH_DAY"."BASE_CURR_CD" IS '기준통화 코드'; COMMENT ON COLUMN "TB_EXCH_DAY"."QUOTE_CURR_CD" IS '표시통화 코드'; COMMENT ON COLUMN "TB_EXCH_DAY"."EXCH_RT" IS '기준통화 1단위당 표시통화 환율'; COMMENT ON COLUMN "TB_EXCH_DAY"."PREV_EXCH_RT" IS '전일 환율'; COMMENT ON COLUMN "TB_EXCH_DAY"."CHG_AMT" IS '전일 대비 환율 변동값'; COMMENT ON COLUMN "TB_EXCH_DAY"."CHG_RT" IS '전일 대비 환율 등락률'; COMMENT ON COLUMN "TB_EXCH_DAY"."HIGH_52W_RT" IS '52주 최고 환율'; COMMENT ON COLUMN "TB_EXCH_DAY"."LOW_52W_RT" IS '52주 최저 환율'; COMMENT ON COLUMN "TB_EXCH_DAY"."PRESS_SCR" IS '환율 압력 점수'; COMMENT ON COLUMN "TB_EXCH_DAY"."DATA_SRC_CD" IS '데이터 출처 코드'; COMMENT ON COLUMN "TB_EXCH_DAY"."DATA_STS" IS '데이터 상태'; COMMENT ON COLUMN "TB_EXCH_DAY"."COLLECT_DTTM" IS '수집일시';

CREATE TABLE "TB_BOND_DAY"("BOND_DAY_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"BASE_DT" DATE NOT NULL,"BOND_CD" VARCHAR(30) NOT NULL,"BOND_NM" VARCHAR(100) NOT NULL,"CNTRY_CD" VARCHAR(10) NOT NULL,"MATURITY_MON" INTEGER,"YLD_RT" NUMERIC(10,6) NOT NULL,"PREV_YLD_RT" NUMERIC(10,6),"CHG_BP" NUMERIC(10,4),"RATE_PRESS_SCR" NUMERIC(10,4),"DATA_SRC_CD" VARCHAR(30) NOT NULL,"DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',"COLLECT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PK_TB_BOND_DAY" PRIMARY KEY("BOND_DAY_ID"),CONSTRAINT "UK_TB_BOND_DAY_01" UNIQUE("BASE_DT","BOND_CD"),CONSTRAINT "CK_TB_BOND_DAY_01" CHECK("MATURITY_MON" IS NULL OR "MATURITY_MON">0),CONSTRAINT "CK_TB_BOND_DAY_02" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR')));
CREATE INDEX "IDX_TB_BOND_DAY_01" ON "TB_BOND_DAY"("BOND_CD","BASE_DT" DESC); CREATE INDEX "IDX_TB_BOND_DAY_02" ON "TB_BOND_DAY"("BASE_DT" DESC);
COMMENT ON TABLE "TB_BOND_DAY" IS '국가별 주요 채권금리 일별 데이터'; COMMENT ON COLUMN "TB_BOND_DAY"."BOND_DAY_ID" IS '일별 채권금리 ID'; COMMENT ON COLUMN "TB_BOND_DAY"."BASE_DT" IS '채권금리 기준일'; COMMENT ON COLUMN "TB_BOND_DAY"."BOND_CD" IS '채권금리 코드'; COMMENT ON COLUMN "TB_BOND_DAY"."BOND_NM" IS '채권금리명'; COMMENT ON COLUMN "TB_BOND_DAY"."CNTRY_CD" IS '국가 코드'; COMMENT ON COLUMN "TB_BOND_DAY"."MATURITY_MON" IS '만기 개월 수'; COMMENT ON COLUMN "TB_BOND_DAY"."YLD_RT" IS '채권 수익률(퍼센트)'; COMMENT ON COLUMN "TB_BOND_DAY"."PREV_YLD_RT" IS '전일 채권 수익률'; COMMENT ON COLUMN "TB_BOND_DAY"."CHG_BP" IS '전일 대비 수익률 변동(bp)'; COMMENT ON COLUMN "TB_BOND_DAY"."RATE_PRESS_SCR" IS '금리 압력 점수'; COMMENT ON COLUMN "TB_BOND_DAY"."DATA_SRC_CD" IS '데이터 출처 코드'; COMMENT ON COLUMN "TB_BOND_DAY"."DATA_STS" IS '데이터 상태'; COMMENT ON COLUMN "TB_BOND_DAY"."COLLECT_DTTM" IS '수집일시';
